#' Read Coverage of a Gene per Group of Cells
#'
#' Plots the read coverage of a gene for each group of cells (e.g. cell types) from the BAM files of the
#' reads used by SCALPEL (\code{<outdir>/filtered_bams/<sample>_filtered.bam}), with the structure of its
#' isoforms. The reads of each group are selected from the BAM files with the cell barcodes of the Seurat
#' object (no intermediate BAM file), and the coverage is normalized by the number of cells of the group.
#'
#' @param seurat_obj iDGE Seurat object generated by SCALPEL (or any Seurat object whose cells are the cells
#'   of the BAM files).
#' @param bamfiles Named vector of BAM files, names = sample names (\code{sample_by} values), e.g.
#'   \code{c(SRR6129050 = "results/filtered_bams/SRR6129050_filtered.bam", ...)}.
#' @param gene_in Gene name.
#' @param genome_gr GTF \code{GRanges} (e.g. \code{rtracklayer::import("annotation.gtf.gz")}).
#' @param group_by Metadata column with the groups of cells (one coverage track per group).
#' @param features Optional transcript names to draw. Default: the isoforms of the gene in the Seurat
#'   object (SCALPEL isoforms), or all transcripts of the gene if none.
#' @param groups Optional subset / order of the groups to plot.
#' @param sample_by Metadata column with the sample of each cell (names of \code{bamfiles}). Default
#'   \code{"orig.ident"}.
#' @param barcode_col Metadata column with the cell barcode as in the BAM tag. Default \code{"Barcodes"}.
#' @param tag BAM tag of the cell barcode: \code{"CB"} (10x, STARsolo) or \code{"XC"} (Drop-seq).
#' @param stranded Keep only the reads on the strand of the gene (3'-tagged libraries). Default \code{TRUE}.
#' @param distZOOM Optional. Plot only the last \code{distZOOM} nt of the gene (3' end side).
#' @param extend Number of nt plotted beyond the 3' end of the gene (reads downstream of the annotation).
#'   Default 1000.
#' @param samtools.bin Path to \code{samtools}. Default \code{"samtools"}.
#'
#' @return A \code{patchwork} / \code{ggplot} object: coverage per group (reads per 1000 cells) above the
#'   isoform structures (thick: CDS, thin: UTR).
#'
#' @examples
#' \dontrun{
#' gtf = rtracklayer::import("gencode.vM21.annotation.gtf.gz")
#' CoveragePlot(idge, bamfiles = c(SRR6129050 = "results/filtered_bams/SRR6129050_filtered.bam",
#'                                 SRR6129051 = "results/filtered_bams/SRR6129051_filtered.bam"),
#'              gene_in = "Reep1", genome_gr = gtf, group_by = "celltype", distZOOM = 4000)
#' }
#'
#' @export
CoveragePlot <- function(
    seurat_obj,
    bamfiles,
    gene_in,
    genome_gr,
    group_by,
    features = NULL,
    groups = NULL,
    sample_by = "orig.ident",
    barcode_col = "Barcodes",
    tag = "CB",
    stranded = TRUE,
    distZOOM = NULL,
    extend = 1000,
    samtools.bin = "samtools") {
  # checks
  meta <- seurat_obj[[]]
  for (col in c(group_by, sample_by, barcode_col)) {
    if (!(col %in% colnames(meta))) stop("Error: ", col, " not found in Seurat object !")
  }
  if (is.null(names(bamfiles)) || !all(names(bamfiles) %in% meta[[sample_by]])) {
    stop("bamfiles must be named by sample (", sample_by, " values: ", paste(unique(meta[[sample_by]]), collapse = ", "), ")")
  }

  #- cells of each group (barcodes per sample)...
  cells <- data.table::data.table(sample = as.character(meta[[sample_by]]), barcode = as.character(meta[[barcode_col]]), group = as.character(meta[[group_by]]))
  cells <- cells[!is.na(group)]
  if (!is.null(groups)) cells <- cells[group %in% groups]
  lv <- if (is.null(groups)) sort(unique(cells$group)) else groups
  n_cells <- cells[, .N, by = group]

  #- isoform structures (exons, CDS) of the gene...
  gtab <- data.table::as.data.table(genome_gr[!is.na(genome_gr$gene_name) & genome_gr$gene_name == gene_in & genome_gr$type %in% c("exon", "CDS")])
  if (nrow(gtab) == 0) stop("Gene ", gene_in, " not found in genome_gr")
  gtab[, `:=`(seqnames = as.character(seqnames), strand = as.character(strand))]
  if (is.null(features)) {
    iso <- sub(".*\\*\\*\\*", "", grep(paste0("^", gene_in, "\\*\\*\\*"), rownames(seurat_obj), value = TRUE))
    features <- if (length(intersect(iso, gtab$transcript_name)) > 0) intersect(iso, gtab$transcript_name) else unique(gtab$transcript_name)
  }
  gtab <- gtab[transcript_name %in% features]
  chr <- gtab$seqnames[1]
  str <- gtab$strand[1]

  #- plotted region: gene (+ extension beyond the 3' end), or the last distZOOM nt...
  from <- min(gtab$start)
  to <- max(gtab$end)
  if (str == "+") {
    to <- to + extend
    if (!is.null(distZOOM)) from <- max(from, max(gtab$end) - distZOOM)
  } else {
    from <- max(1, from - extend)
    if (!is.null(distZOOM)) to <- min(to, min(gtab$start) + distZOOM)
  }

  #- coverage per group from the reads of the region (CIGAR M/D/=/X operations, N skipped)...
  cov <- data.table::rbindlist(lapply(names(bamfiles), function(s) {
    #- flag, position, CIGAR and cell barcode of the reads of the region...
    awk <- paste0("awk -F'\\t' -v OFS='\\t' '{bc=\"NA\"; for(i=12;i<=NF;i++) if(substr($i,1,5)==\"", tag, ":Z:\") bc=substr($i,6); print $2,$4,$6,bc}'")
    cmd <- paste0(samtools.bin, " view -F 4 ", shQuote(bamfiles[[s]]), " ", chr, ":", from, "-", to, " | ", awk)
    reads <- tryCatch(
      data.table::fread(cmd = cmd, sep = "\t", header = FALSE, col.names = c("flag", "pos", "cigar", "barcode"),
                        colClasses = c("integer", "integer", "character", "character"), showProgress = FALSE),
      error = function(e) data.table::data.table())
    if (nrow(reads) == 0 || ncol(reads) < 4) return(NULL)
    keep <- reads$barcode %in% cells[sample == s]$barcode
    if (stranded) keep <- keep & (bitwAnd(reads$flag, 16L) > 0) == (str == "-")
    r <- reads[keep]
    if (nrow(r) == 0) return(NULL)
    r[, group := cells[sample == s][match(r$barcode, barcode)]$group]
    #- aligned blocks of each read (vectorized over the CIGAR operations)...
    ops <- regmatches(r$cigar, gregexpr("[0-9]+[MIDNSHP=X]", r$cigar))
    idx <- rep(seq_along(ops), lengths(ops))
    ops <- unlist(ops)
    len <- as.integer(sub("[A-Z=]$", "", ops))
    op <- sub("^[0-9]+", "", ops)
    ref <- ifelse(op %in% c("M", "D", "N", "=", "X"), len, 0L)
    offset <- stats::ave(ref, idx, FUN = cumsum) - ref
    st <- r$pos[idx] + offset
    blocks <- data.table::data.table(group = r$group[idx], start = st, end = st + len - 1)[op %in% c("M", "D", "=", "X")]
    return(blocks)
  }))

  positions <- from:to
  depth <- data.table::rbindlist(lapply(lv, function(g) {
    b <- if (is.null(cov) || nrow(cov) == 0) NULL else cov[group == g]
    d <- numeric(length(positions) + 1)
    if (!is.null(b) && nrow(b) > 0) {
      s <- pmax(b$start, from) - from + 1
      e <- pmin(b$end, to) - from + 1
      ok <- s <= e
      d <- d + tabulate(s[ok], length(d)) - tabulate(e[ok] + 1, length(d))
    }
    n <- n_cells[group == g]$N
    data.table::data.table(group = g, position = positions, depth = cumsum(d)[seq_along(positions)] / max(n, 1) * 1000)
  }))
  depth[, group := factor(paste0(group, " (", n_cells$N[match(group, n_cells$group)], " cells)"),
    levels = paste0(lv, " (", n_cells$N[match(lv, n_cells$group)], " cells)"))]

  #- coverage tracks...
  p_cov <- ggplot2::ggplot(depth, ggplot2::aes(position, depth)) +
    ggplot2::geom_area(fill = "#38B6A3", color = "#1f6f63", linewidth = .2) +
    ggplot2::facet_wrap(~group, ncol = 1, strip.position = "top") +
    ggplot2::coord_cartesian(xlim = c(from, to), expand = FALSE) +
    ggplot2::ylab("reads per 1000 cells") +
    ggplot2::xlab(NULL) +
    ggplot2::ggtitle(paste0(gene_in, " (", chr, ":", from, "-", to, ", ", str, " strand)")) +
    ggplot2::theme_bw(base_size = 12) +
    ggplot2::theme(strip.text = ggplot2::element_text(hjust = 0, size = 10), strip.background = ggplot2::element_blank(),
                   axis.text.x = ggplot2::element_blank(), axis.ticks.x = ggplot2::element_blank(), panel.grid.minor = ggplot2::element_blank())

  #- isoform structures (thick: CDS, thin: exon / UTR)...
  tr <- sort(unique(gtab$transcript_name), decreasing = TRUE)
  gtab[, y := match(transcript_name, tr)]
  span <- gtab[type == "exon", .(start = min(start), end = max(end)), by = .(transcript_name, y)]
  p_gene <- ggplot2::ggplot() +
    ggplot2::geom_segment(data = span, ggplot2::aes(x = pmax(start, from), xend = pmin(end, to), y = y, yend = y), linewidth = .4) +
    ggplot2::geom_rect(data = gtab[type == "exon"], ggplot2::aes(xmin = pmax(start, from), xmax = pmin(end, to), ymin = y - .15, ymax = y + .15), fill = "gray40") +
    ggplot2::geom_rect(data = gtab[type == "CDS"], ggplot2::aes(xmin = pmax(start, from), xmax = pmin(end, to), ymin = y - .3, ymax = y + .3), fill = "gray20") +
    ggplot2::scale_y_continuous(breaks = seq_along(tr), labels = tr) +
    ggplot2::coord_cartesian(xlim = c(from, to), expand = FALSE) +
    ggplot2::xlab(paste0(chr, " (nt)")) +
    ggplot2::ylab(NULL) +
    ggplot2::theme_bw(base_size = 12) +
    ggplot2::theme(panel.grid = ggplot2::element_blank())

  return(patchwork::wrap_plots(p_cov, p_gene, ncol = 1, heights = c(length(lv), max(1, length(tr) * .35))))
}
